// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.eclipse.rdf4j.sail.lmdb.frontier.SyntheticQuadSnapshot.predicate;
import static org.eclipse.rdf4j.sail.lmdb.frontier.SyntheticQuadSnapshot.qError;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.ArrayList;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The Omni bridge estimator samples one side of a join and probes degrees on the other. A sampled zero from the forward
 * orientation is not knowledge: when the sample never reaches the rows that carry the join (a hidden hub), the reverse
 * orientation has to be consulted, and when neither orientation has any witness the answer is a typed unknown, never a
 * point zero with {@link FrontierFallbackReason#NONE}.
 */
class FrontierOmniBridgeOrientationTest {

	private static final long HUB = 5_000_000L;

	/**
	 * Eight p7 rows reach a hub that has 20,000 p8 rows; the other 20,000 p7 rows are singletons. Sampling p7 misses
	 * the hub almost surely, sampling p8 sees it in about half of the sampled rows.
	 */
	@Test
	void hiddenHubBridgeIsNotEstimatedAsEmpty(@TempDir Path directory) throws Exception {
		SyntheticQuadSnapshot snapshot = hiddenHub(false);
		try (LmdbStatisticsService service = build(directory, snapshot)) {
			FrontierJoinProbe forward = new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0);
			FrontierJoinProbe reverse = new FrontierJoinProbe(predicate(8L), 0, predicate(7L), 2);
			long exact = snapshot.exactPredicateJoin(7L, 2, 8L, 0);
			FrontierJoinEstimate forwardEstimate = service.estimateJoin(snapshot.snapshotEpoch(), forward);
			FrontierJoinEstimate reverseEstimate = service.estimateJoin(snapshot.snapshotEpoch(), reverse);
			assertEquals(160_000L, exact);
			assertEquals(FrontierFallbackReason.NONE, forwardEstimate.fallbackReason(), forwardEstimate::toString);
			assertTrue(forwardEstimate.pointRows() >= exact / 16.0d,
					"p7.o = p8.s forward estimate must stay within q-error 16 of exact=" + exact + " but was "
							+ forwardEstimate + " (reverse orientation gives " + reverseEstimate + ")");
			assertTrue(reverseEstimate.pointRows() >= exact / 16.0d, reverseEstimate::toString);
			assertTrue(forwardEstimate.upperRows() >= exact, "the interval must still cover exact: " + forwardEstimate);
		}
	}

	/** Same shape with the hub on the other side, so the probe that used to work is now the weak one. */
	@Test
	void mirroredHiddenHubBridgeIsNotEstimatedAsEmpty(@TempDir Path directory) throws Exception {
		SyntheticQuadSnapshot snapshot = hiddenHub(true);
		try (LmdbStatisticsService service = build(directory, snapshot)) {
			FrontierJoinProbe probe = new FrontierJoinProbe(predicate(8L), 0, predicate(7L), 2);
			long exact = snapshot.exactPredicateJoin(8L, 0, 7L, 2);
			FrontierJoinEstimate estimate = service.estimateJoin(snapshot.snapshotEpoch(), probe);
			assertEquals(160_000L, exact);
			assertEquals(FrontierFallbackReason.NONE, estimate.fallbackReason(), estimate::toString);
			assertTrue(estimate.pointRows() >= exact / 16.0d,
					"p8.s = p7.o estimate must stay within q-error 16 of exact=" + exact + " but was " + estimate);
			assertTrue(estimate.upperRows() >= exact, "the interval must still cover exact: " + estimate);
		}
	}

	/**
	 * Two large predicates whose join keys are disjoint: both orientations sample rows whose degree on the other side
	 * is exactly zero, so neither has a witness. That is the absence of evidence, not evidence of an empty join.
	 */
	@Test
	void bothOrientationsWithoutAnyWitnessYieldATypedUnknownInsteadOfAPointZero(@TempDir Path directory)
			throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int i = 1; i <= 20_000; i++) {
			rows.add(new long[] { 1_000_000L + i, 7L, 2_000_000L + i, 0L });
			rows.add(new long[] { 7_000_000L + i, 8L, 8_000_000L + i, 0L });
		}
		SyntheticQuadSnapshot snapshot = new SyntheticQuadSnapshot(94L, rows);
		try (LmdbStatisticsService service = build(directory, snapshot);
				FrontierStatisticsLease lease = service.acquire(snapshot.snapshotEpoch())) {
			assertTrue(lease.ready());
			FrontierOmniIndex omni = new FrontierOmniIndex(service.currentManifest().orElseThrow(), lease.shards());
			FrontierJoinProbe probe = new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0);
			FrontierJoinEstimate omniEstimate = omni.estimateJoin(probe, new FrontierOmniIndex.Scratch());
			assertEquals(FrontierFallbackReason.CONFIDENCE_TOO_WIDE, omniEstimate.fallbackReason(),
					"a zero-witness sampled bridge in both orientations is a typed unknown: " + omniEstimate);

			FrontierJoinEstimate mapped = service.estimateJoin(snapshot.snapshotEpoch(), probe);
			assertFalse(mapped.fallbackReason() == FrontierFallbackReason.NONE && mapped.pointRows() == 0.0d
					&& mapped.confidence() == 0.0d,
					"the planner-facing estimate must never be a zero-confidence point zero: " + mapped);
		}
	}

	/**
	 * A join on a bound component is the product of two leaf estimates, one of them bound to the join key. When that
	 * bound leaf is a sampled zero (no sampled row matched, the interval still admits rows), the product is the same
	 * absence of evidence as a zero-witness bridge and must not reach the planner as a {@code NONE} point zero. Both
	 * orientations of a product are identical, so there is no other orientation to consult.
	 */
	@Test
	void boundJoinKeyWithASampledZeroLeafIsATypedUnknownInsteadOfAPointZero(@TempDir Path directory)
			throws Exception {
		SyntheticQuadSnapshot snapshot = correlated();
		try (LmdbStatisticsService service = SyntheticQuadSnapshot.buildService(directory, snapshot,
				FrontierStatisticsBuildConfig.testing(32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L));
				FrontierStatisticsLease lease = service.acquire(snapshot.snapshotEpoch())) {
			assertTrue(lease.ready());
			FrontierOmniIndex omni = new FrontierOmniIndex(service.currentManifest().orElseThrow(), lease.shards());
			StringBuilder violations = new StringBuilder();
			for (int leftComponent = 0; leftComponent < 4; leftComponent++) {
				for (int rightComponent = 0; rightComponent < 4; rightComponent++) {
					if (leftComponent != 1 && rightComponent != 1) {
						continue;
					}
					FrontierJoinProbe probe = new FrontierJoinProbe(predicate(7L), leftComponent, predicate(8L),
							rightComponent);
					long exact = snapshot.exactPredicateJoin(7L, leftComponent, 8L, rightComponent);
					FrontierJoinEstimate omniEstimate = omni.estimateJoin(probe, new FrontierOmniIndex.Scratch());
					FrontierJoinEstimate mapped = service.estimateJoin(snapshot.snapshotEpoch(), probe);
					String pair = leftComponent + "->" + rightComponent + " exact=" + exact;
					if (unsupportedZero(omniEstimate)) {
						violations.append("\n  omni ").append(pair).append(' ').append(omniEstimate);
					}
					if (unsupportedZero(mapped)) {
						violations.append("\n  mapped ").append(pair).append(' ').append(mapped);
					}
					if (mapped.fallbackReason() == FrontierFallbackReason.NONE
							&& (exact < mapped.lowerRows() || exact > mapped.upperRows())) {
						violations.append("\n  EXCLUDED ").append(pair).append(' ').append(mapped);
					}
				}
			}
			assertTrue(violations.length() == 0,
					"a bound-key product whose bound leaf is a sampled zero is not evidence of an empty join:"
							+ violations);
		}
	}

	/** A point zero reported as an answer while its own interval admits rows, i.e. a zero that is not exact. */
	private static boolean unsupportedZero(FrontierJoinEstimate estimate) {
		return estimate.fallbackReason() == FrontierFallbackReason.NONE && estimate.pointRows() == 0.0d
				&& estimate.upperRows() > 0.0d;
	}

	/** 100 subjects with 60 p7 objects and 40 p8 objects each; terms 7 and 8 never occur as objects. */
	private static SyntheticQuadSnapshot correlated() {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int subject = 1; subject <= 100; subject++) {
			for (int row = 0; row < 60; row++) {
				rows.add(new long[] { subject, 7L, 10_000L + subject * 100L + row, 0L });
			}
			for (int row = 0; row < 40; row++) {
				rows.add(new long[] { subject, 8L, 20_000L + subject * 100L + row, 0L });
			}
		}
		return new SyntheticQuadSnapshot(77L, rows);
	}

	/**
	 * Regression guards (passing before and after the orientation fix): sixteen predicate pairs with disjoint heavy
	 * hitters and a modest shared key set. The estimator must keep exact inside the interval and never collapse.
	 */
	@Test
	void disjointHeavyHittersKeepExactInsideReportedInterval(@TempDir Path directory) throws Exception {
		assertDisjointHeavyHitters(directory, 60, 4, FrontierLeafProbe.BOTH_PLANES);
	}

	@Test
	void rareSharedKeysKeepExactInsideReportedInterval(@TempDir Path directory) throws Exception {
		assertDisjointHeavyHitters(directory, 3, 40, FrontierLeafProbe.BOTH_PLANES);
	}

	@Test
	void rareSharedKeysExplicitPlaneAgmsFallbackKeepsExactInsideInterval(@TempDir Path directory)
			throws Exception {
		assertDisjointHeavyHitters(directory, 1, 70, FrontierLeafProbe.EXPLICIT);
	}

	private static SyntheticQuadSnapshot hiddenHub(boolean mirrored) {
		ArrayList<long[]> rows = new ArrayList<>();
		if (!mirrored) {
			for (int i = 1; i <= 20_000; i++) {
				rows.add(new long[] { 1_000_000L + i, 7L, 2_000_000L + i, 0L });
			}
			for (int j = 1; j <= 8; j++) {
				rows.add(new long[] { 3_000_000L + j, 7L, HUB, 0L });
			}
			for (int m = 1; m <= 20_000; m++) {
				rows.add(new long[] { HUB, 8L, 6_000_000L + m, 0L });
				rows.add(new long[] { 7_000_000L + m, 8L, 8_000_000L + m, 0L });
			}
		} else {
			for (int i = 1; i <= 20_000; i++) {
				rows.add(new long[] { 1_000_000L + i, 7L, HUB, 0L });
				rows.add(new long[] { 1_100_000L + i, 7L, 2_000_000L + i, 0L });
			}
			for (int j = 1; j <= 8; j++) {
				rows.add(new long[] { HUB, 8L, 9_000_000L + j, 0L });
			}
			for (int m = 1; m <= 20_000; m++) {
				rows.add(new long[] { 7_000_000L + m, 8L, 8_000_000L + m, 0L });
			}
		}
		return new SyntheticQuadSnapshot(91L, rows);
	}

	private static LmdbStatisticsService build(Path directory, SyntheticQuadSnapshot snapshot) throws Exception {
		return SyntheticQuadSnapshot.buildService(directory, snapshot, FrontierStatisticsBuildConfig.testing(
				512L * 1024L * 1024L, 1024, 256, 256, 2L * 1024L * 1024L));
	}

	private static void assertDisjointHeavyHitters(Path directory, int sharedKeys, int sharedDegree, int planeMask)
			throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		int pairs = 16;
		int heavyRows = 3_000;
		long nextSubject = 10_000_000L;
		long nextObject = 50_000_000L;
		for (int pair = 0; pair < pairs; pair++) {
			long left = 100L + 2L * pair;
			long right = left + 1L;
			long heavyLeft = 90_000_000L + pair;
			long heavyRight = 91_000_000L + pair;
			for (int row = 0; row < heavyRows; row++) {
				rows.add(new long[] { nextSubject++, left, heavyLeft, 0L });
				rows.add(new long[] { heavyRight, right, nextObject++, 0L });
			}
			for (int key = 0; key < sharedKeys; key++) {
				long shared = 92_000_000L + pair * 1_000L + key;
				for (int degree = 0; degree < sharedDegree; degree++) {
					rows.add(new long[] { nextSubject++, left, shared, 0L });
					rows.add(new long[] { shared, right, nextObject++, 0L });
				}
			}
		}
		SyntheticQuadSnapshot snapshot = new SyntheticQuadSnapshot(92L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				64L * 1024L * 1024L, 64, 256, 256, 2L * 1024L * 1024L);
		try (LmdbStatisticsService service = SyntheticQuadSnapshot.buildService(directory, snapshot, config)) {
			int excluded = 0;
			int collapsed = 0;
			double worstQ = 1.0d;
			StringBuilder report = new StringBuilder();
			for (int pair = 0; pair < pairs; pair++) {
				long left = 100L + 2L * pair;
				long right = left + 1L;
				long exact = snapshot.exactPredicateJoin(left, 2, right, 0);
				FrontierJoinEstimate estimate = service.estimateJoin(snapshot.snapshotEpoch(),
						new FrontierJoinProbe(predicate(left, planeMask), 2, predicate(right, planeMask), 0));
				if (estimate.fallbackReason() != FrontierFallbackReason.NONE) {
					report.append("\n  pair=")
							.append(pair)
							.append(" exact=")
							.append(exact)
							.append(" UNKNOWN (typed fallback, not a claim) ")
							.append(estimate);
					continue;
				}
				double q = qError(estimate.pointRows(), exact);
				worstQ = Math.max(worstQ, q);
				boolean outside = exact < estimate.lowerRows() || exact > estimate.upperRows();
				if (outside) {
					excluded++;
				}
				if (estimate.pointRows() < exact / 100.0d) {
					collapsed++;
				}
				report.append("\n  pair=")
						.append(pair)
						.append(" exact=")
						.append(exact)
						.append(" q=")
						.append(String.format("%.1f", q))
						.append(outside ? " EXCLUDED " : " ")
						.append(estimate);
			}
			assertTrue(excluded == 0 && collapsed == 0 && worstQ <= 16.0d,
					"join estimates must keep exact inside [lower, upper] and within q-error 16; worstQ=" + worstQ
							+ ", excluded=" + excluded + ", collapsed(point<exact/100)=" + collapsed + report);
		}
	}
}
